cypress_script:
describe('Notification Messages Page', () => {
  it('should display the notification message on successful action', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('h1').contains('Notification Message');
    cy.get('#flash-messages').should('be.visible');
    cy.url().should('include', '/notification_message_rendered');
  });

  it('should not display any messages when the page is loaded without actions', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('#flash-messages').should('not.exist');
    cy.url().should('include', '/notification_message_rendered');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Notification Messages Page', () => {
  test('should display the notification message on successful action', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await expect(page.locator('h1')).toHaveText('Notification Message');
    await expect(page.locator('#flash-messages')).toBeVisible();
    await expect(page).toHaveURL(/notification_message_rendered/);
  });

  test('should not display any messages when the page is loaded without actions', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await expect(page.locator('#flash-messages')).toHaveCount(0);
    await expect(page).toHaveURL(/notification_message_rendered/);
  });
});
